export type StorageAccountsVersion =
  | '4.40'
  | '4.41';

/** Storage account. A managed S3-compatible object store on SeaweedFS, with replicated volume servers, a filer and a scalable S3 gateway. */
export interface StorageAccountsData {
  /** The region the account is billed in. */
  location: string;
  /** The account's own settings. */
  properties?: {
    /** The cluster whose namespace holds the object store. */
    clusterId: string;
    /** The S3 gateway — docs/plan/15's ADR-008: "the API is S3". */
    gateway?: {
      /** Number of S3 gateway pods. The gateway is stateless, so this is a throughput and availability setting rather than a topology one. */
      replicas: number;
    };
    /** Number of master servers. The masters hold the volume topology in a Raft group, so three is the smallest count that survives losing one. One is offered for development and has no quorum at all. */
    masters: number;
    /** What the platform scrapes. */
    monitoring?: {
      /** Whether the operator is asked for a ServiceMonitor per component. On by default — docs/plan/12: "a managed service the tenant cannot see the health of is a black box they will not trust with production". Turning it off removes the metrics port as well as the scrape, which is the operator's own behaviour rather than this provider's. */
      enabled?: boolean;
    };
    /** Where the second copy of every object is placed. None keeps one copy and is for scratch data only. A placement the cluster's topology cannot satisfy leaves volumes read-only rather than failing the create. Immutable, because SeaweedFS applies this to volumes as they are created and never rewrites the ones that already exist — a change would split the account into two durability promises with no way to tell which object got which. */
    replication: StorageAccountsReplication;
    /** CPU and memory per volume server, either by preset or explicitly. The masters, the filer and the S3 gateway are sized by the platform and are not affected. */
    sizing?: {
      /** Explicit vCPU quantity in Kubernetes form, for example 500m or 2. Empty means take it from the preset. */
      cpu?: string;
      /** Explicit memory quantity in Kubernetes form, for example 4Gi. Empty means take it from the preset. */
      memory?: string;
      /** A sizing preset from docs/plan/12. Volume servers use the s1 family, which is 1 vCPU to 4 GiB. */
      preset?: StorageAccountsPreset;
    };
    /** The data volume, per volume server. */
    storage?: {
      /** StorageClass name for the volume servers. Empty means the cluster default. */
      class?: string;
      /** Data volume size per volume server, in Kubernetes quantity form. Grows online; never shrinks. */
      size: string;
    };
    /** SeaweedFS version. ⚠ SeaweedFS ships a release roughly weekly and maintains no long-term branch, so docs/plan/12's "supported major versions" is a shape this project does not have; the two values here are the two most recent releases and a new api-version is what adds a third. */
    version: StorageAccountsVersion;
    /** Number of volume servers. This is the capacity axis: total raw capacity is this count times the volume size below, before replication. */
    volumeServers: number;
  };
  /** Key/value tags, at most 50 pairs — docs/plan/06 § Tags, locks. Values are strings; the cap applies to the merged set, so a PATCH that adds one tag to a full bag is refused. */
  tags?: Record<string, string>;
}

/** One Storage account, as the API returns it. */
export interface StorageAccountsResource {
  /** The resource's fully qualified id. */
  readonly id: string;
  readonly name: string;
  readonly type: 'CyberCloud.Storage/accounts';
  readonly properties?: StorageAccountsData['properties'];
}

/** What listKeys returns. ⚠ Secret material — never log or persist this. */
export interface StorageAccountsListKeysResult {
  /** The access key id. Not secret on its own; useless without the pair below. */
  accessKeyId: string;
  /** The in-cluster S3 endpoint, http://host:port. ⚠ No external address is returned, because there is none — see the account's own documentation on exposure. */
  endpoint: string;
  /** The region name an S3 client signs with. SeaweedFS does not route on it, and SigV4 refuses to sign without one, so it is returned rather than left for the caller to guess. */
  region: string;
  /** The secret access key, read from the tenant's Vault for this call only. */
  secretAccessKey: string;
}

/** Bucket. An S3 bucket inside a managed object-storage account, with an optional size limit and optional object versioning. */
export interface StorageAccountsBucketsData {
  /** The region the bucket is billed in. */
  location: string;
  /** The bucket's own settings. */
  properties?: {
    /** The cluster whose namespace holds the bucket. Must be the cluster the account is in — nothing checks that, and a bucket placed elsewhere is applied into a namespace with no object store in it. */
    clusterId: string;
    /** How much the bucket may hold. */
    quota?: {
      /** The bucket's size limit, in Kubernetes quantity form. Empty means no limit other than the account's own provisioned capacity. ⚠ This is a limit inside capacity the account already reserved; it does not add any, and it is not what the bucket is billed on. */
      size?: string;
    };
    /** Whether the bucket keeps previous versions of an overwritten object. Off by default. ⚠ docs/plan/15 § Object storage: SeaweedFS' S3 implementation is "good but not complete" and names object versioning as one of the partial areas, so the supported-operations table for the deployed version — not this property — is what says how completely it behaves. */
    versioning?: boolean;
  };
  /** Key/value tags, at most 50 pairs — docs/plan/06 § Tags, locks. Values are strings; the cap applies to the merged set, so a PATCH that adds one tag to a full bag is refused. */
  tags?: Record<string, string>;
}

/** One Bucket, as the API returns it. */
export interface StorageAccountsBucketsResource {
  /** The resource's fully qualified id. */
  readonly id: string;
  readonly name: string;
  readonly type: 'CyberCloud.Storage/accounts/buckets';
  readonly properties?: StorageAccountsBucketsData['properties'];
}

/** What stats returns. */
export interface StorageAccountsBucketsStatsResult {
  /** How many objects the bucket holds, as of the last sample. */
  objectCount: number;
  /** When the two figures above were sampled, RFC 3339. ⚠ Returned because a sampled number with no timestamp is a number a caller will read as live. */
  sampledAt: string;
  /** How many bytes the bucket holds before replication, as of the last sample. ⚠ Sampled rather than live — docs/plan/15 § Metering samples SeaweedFS volume stats hourly per bucket — so it is not a number to write an assertion against immediately after a PUT. */
  sizeBytes: number;
}

/** The values /properties/image/variant accepts. ⚠ Closed: the write path refuses anything else. */
export type TerminalConsolesVariant =
  | 'default'
  | 'minimal';

/** The values /properties/network/egress accepts. ⚠ Closed: the write path refuses anything else. */
export type TerminalConsolesEgress =
  | 'Internet'
  | 'TenantOnly';

/** The values /properties/sizing/preset accepts. ⚠ Closed: the write path refuses anything else. */
export type TerminalConsolesPreset =
  | 'c1.large'
  | 'c1.medium'
  | 'c1.small';

/** Cloud terminal. A browser shell running in this subscription's own cluster, holding a managed identity, with a persistent home directory and no stored credential. */
export interface TerminalConsolesData {
  /** The region the console is billed in. */
  location: string;
  /** The console's own settings. */
  properties?: {
    /** docs/plan/19 § Auditing. Who, when, from where, which subscription and for how long is always recorded and is not a setting. */
    audit?: {
      /** Whether everything typed into and printed by this shell is recorded. ⚠ Off by default and immutable afterwards: a shell contains secrets, a keystroke log is a liability, and a recording that could be switched off mid-life would be worth nothing to the compliance requirement it exists for. */
      sessionRecording?: boolean;
    };
    /** The cluster whose namespace holds the shell and its home volume. */
    clusterId: string;
    /** The persistent home directory. The only part of a console that survives an idle reclaim. */
    home?: {
      /** How long $HOME is kept after the console was last attached to. ⚠ Nothing sweeps on it yet — it is carried so that a console created today is swept correctly by whatever does. */
      retentionDays?: number;
      /** The size of $HOME. It grows and never shrinks: a PersistentVolumeClaim refuses a decrease at the API. */
      size: string;
    };
    /** Who the shell runs as. */
    identity?: {
      /** The managed identity every command in this shell acts as. It may not be changed: a console whose identity moved would have an audit trail describing a shell that no longer exists. */
      principalId: string;
    };
    /** Which shell image to run. */
    image?: {
      /** default carries every tool in docs/plan/19's table and takes about 40 seconds to pull cold; minimal carries shells, editors, cyc and kubectl and starts in about 8. The repository and the digest are the platform's. */
      variant?: TerminalConsolesVariant;
    };
    /** What the shell may reach. Nothing may ever reach the shell. */
    network?: {
      /** Internet lets the shell reach public addresses as well as this subscription's own workloads and DNS — a shell that cannot git clone is not a shell. TenantOnly removes the public half and leaves the rest. */
      egress?: TerminalConsolesEgress;
    };
    /** When a shell stops. Both numbers are ceilings a tenant may lower and neither may be turned off. */
    session?: {
      /** How long a shell may sit with nobody typing into it before it is reclaimed. The home volume survives; the pod does not. ⚠ There is no value meaning never — an idle terminal is a tenant paying for something they closed. */
      idleTimeoutMinutes?: number;
      /** The longest a single shell may run, busy or not. Enforced by the kubelet through the pod's own deadline, so it holds even when nothing of this platform is running. */
      maxDurationHours?: number;
    };
    /** CPU and memory for the shell. */
    sizing?: {
      /** How much a shell gets. The ladder stops at 2 vCPU and 4 GiB, which is docs/plan/19's ceiling for this row — a workload that needs more needs a cluster and a job rather than a terminal. */
      preset?: TerminalConsolesPreset;
    };
  };
  /** Key/value tags, at most 50 pairs — docs/plan/06 § Tags, locks. Values are strings; the cap applies to the merged set, so a PATCH that adds one tag to a full bag is refused. */
  tags?: Record<string, string>;
}

/** One Cloud terminal, as the API returns it. */
export interface TerminalConsolesResource {
  /** The resource's fully qualified id. */
  readonly id: string;
  readonly name: string;
  readonly type: 'CyberCloud.Terminal/consoles';
  readonly properties?: TerminalConsolesData['properties'];
}

/** What connect returns. */
export interface TerminalConsolesConnectResult {
  /** The SignalR hub path to open. docs/plan/10 § SignalR. */
  hub: string;
  /** How long this shell may sit idle before it is reclaimed. Shown to the person, because a terminal that vanishes without warning reads as a bug. */
  idleTimeoutSeconds: number;
  /** How long this shell may run in total before the kubelet stops it. */
  maxDurationSeconds: number;
  /** Whether this session is being recorded. ⚠ docs/plan/19 § Auditing requires the portal to be loud about this, which is why it is on the connect response rather than only on the resource body: a panel that had to fetch the resource to find out would render one frame of a terminal that lies. */
  recording: boolean;
  /** The session to name on the terminal hub. ⚠ It is the shell pod's own UID, so it changes when a reclaimed console is re-created — which is exactly when a client's replay buffer has become meaningless. */
  sessionId: string;
  /** Starting while the shell is still being scheduled, Ready once it is running. A client opens the hub either way and sees output when there is some. */
  state: string;
}

/** What terminate returns. */
export interface TerminalConsolesTerminateResult {
  /** True when this call stopped a running shell, false when there was none. ⚠ Both are success: the caller's goal is that no shell is running. */
  terminated: boolean;
}
